"""
Deterministic Financial Calculation Engine for Project # hasep.
Enforces all 8 equations using pure Python Decimal (2 decimal places) in JOD.
"""

from decimal import Decimal
from typing import List, Tuple
from backend.app.schemas.financial_form import (
    FinancialFormData,
    CalculationMismatch,
    round_decimal,
)


def recalculate_financial_form(form: FinancialFormData) -> FinancialFormData:
    return _recalculate_financial_form_impl(form)
exec('def _recalculate_financial_form_impl(form: FinancialFormData) -> FinancialFormData:\n    """\n    Executes the 8 deterministic financial equations:\n    1. total_expenses = sum(expenses)\n    2. total_purchases = sum(purchases)\n    3. total_expenses_and_purchases = total_expenses + total_purchases\n    4. net_sale = sales - returns\n    5. total_applications = orders + kareem + ashaayi\n    6. total_sale = total_applications + visa + net_sale\n    7. visa_total = visa\n    8. current_balance = previous_balance + increase - decrease\n    Compares calculated values with extracted handwritten totals and adds\n    CalculationMismatch items if discrepancies exist.\n    """\n    mismatches: List[CalculationMismatch] = []\n    calculated_total_purchases = sum(\n        (round_decimal(p.amount) for p in form.purchases), Decimal("0.00")\n    ).quantize(Decimal("0.01"))\n    calculated_total_expenses = sum(\n        (round_decimal(e.amount) for e in form.expenses), Decimal("0.00")\n    ).quantize(Decimal("0.01"))\n    calculated_total_expenses_and_purchases = (\n        calculated_total_expenses + calculated_total_purchases\n    ).quantize(Decimal("0.01"))\n    gross_sales = round_decimal(form.sales.sales)\n    returns = round_decimal(form.sales.returns)\n    calculated_net_sale = (gross_sales - returns).quantize(Decimal("0.01"))\n    orders = round_decimal(form.sales.orders)\n    kareem = round_decimal(form.sales.kareem)\n    ashaayi = round_decimal(form.sales.ashaayi)\n    calculated_total_applications = (orders + kareem + ashaayi).quantize(Decimal("0.01"))\n    visa = round_decimal(form.sales.visa)\n    calculated_total_sale = (\n        calculated_total_applications + visa + calculated_net_sale\n    ).quantize(Decimal("0.01"))\n    prev_balance = round_decimal(form.summary.previous_balance)\n    increase = round_decimal(form.summary.increase)\n    decrease = round_decimal(form.summary.decrease)\n    calculated_current_balance = (prev_balance + increase - decrease).quantize(Decimal("0.01"))\n    if form.summary.handwritten_current_balance is not None:\n        diff_balance = (\n            form.summary.handwritten_current_balance - calculated_current_balance\n        ).quantize(Decimal("0.01"))\n        if abs(diff_balance) > Decimal("0.00"):\n            mismatches.append(\n                CalculationMismatch(\n                    equation_id="EQ8_CURRENT_BALANCE",\n                    field_name="summary.current_balance",\n                    arabic_label="الرصيد الحالي",\n                    extracted_value=form.summary.handwritten_current_balance,\n                    calculated_value=calculated_current_balance,\n                    difference=diff_balance,\n                    severity="error",\n                    message=(\n                        f"فرق في الرصيد الحالي: المسجل يدوياً {form.summary.handwritten_current_balance} د.أ "\n                        f"يختلف عن المحسوب {calculated_current_balance} د.أ (الفارق: {diff_balance} د.أ)"\n                    ),\n                )\n            )\n    if form.summary.total_purchases != Decimal("0.00") and form.summary.total_purchases != calculated_total_purchases:\n        diff_purchases = (form.summary.total_purchases - calculated_total_purchases).quantize(Decimal("0.01"))\n        if abs(diff_purchases) > Decimal("0.00"):\n            mismatches.append(\n                CalculationMismatch(\n                    equation_id="EQ2_PURCHASES_TOTAL",\n                    field_name="summary.total_purchases",\n                    arabic_label="مجموع المشتريات",\n                    extracted_value=form.summary.total_purchases,\n                    calculated_value=calculated_total_purchases,\n                    difference=diff_purchases,\n                    severity="warning",\n                    message=f"مجموع بنود المشتريات ({calculated_total_purchases} د.أ) لا يطابق المجموع المسجل ({form.summary.total_purchases} د.أ)",\n                )\n            )\n    if form.summary.total_expenses != Decimal("0.00") and form.summary.total_expenses != calculated_total_expenses:\n        diff_expenses = (form.summary.total_expenses - calculated_total_expenses).quantize(Decimal("0.01"))\n        if abs(diff_expenses) > Decimal("0.00"):\n            mismatches.append(\n                CalculationMismatch(\n                    equation_id="EQ1_EXPENSES_TOTAL",\n                    field_name="summary.total_expenses",\n                    arabic_label="مجموع المصاريف",\n                    extracted_value=form.summary.total_expenses,\n                    calculated_value=calculated_total_expenses,\n                    difference=diff_expenses,\n                    severity="warning",\n                    message=f"مجموع بنود المصاريف ({calculated_total_expenses} د.أ) لا يطابق المجموع المسجل ({form.summary.total_expenses} د.أ)",\n                )\n            )\n    form.sales.net_sale = calculated_net_sale\n    form.sales.total_applications = calculated_total_applications\n    form.sales.total_sale = calculated_total_sale\n    form.summary.total_purchases = calculated_total_purchases\n    form.summary.total_expenses = calculated_total_expenses\n    form.summary.total_expenses_and_purchases = calculated_total_expenses_and_purchases\n    form.summary.current_balance = calculated_current_balance\n    form.calculation_mismatches = mismatches\n    form.is_mathematically_valid = len(mismatches) == 0\n    return form\n', globals())
